{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C53","C54","C55","C56","C57","C58","C62","C64","C65","C66","C69","C71"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C53","C54","C55","C56","C57","C58","C62","C64","C65","C66","C69","C71"],
  "claims": [
    {
      "claim": "The query is a morphinan closely related to morphine; L5 records show morphine is rapidly absorbed from the small intestine (C69) and crosses Caco-2 monolayers better than low-permeability markers (C71), supporting adequate intestinal absorption for the query scaffold.",
      "card_ids": ["C69","C71"]
    },
    {
      "claim": "L5 permeability records for rigid phenolic alkaloids and morphinans show high passive permeability and no P-gp efflux (C65/C74, same (-)-SPD measurement; C66 for GA2-50), indicating the query's phenol/amine morphinan is unlikely to be limited by gut-wall efflux.",
      "card_ids": ["C65","C66","C74"]
    },
    {
      "claim": "The P-gp/BCRP efflux records for estrone and estrone-3-sulfate (C68, C72) involve steroids and do not establish the query as an efflux substrate; no L5 record provides affirmative hydromorphone-specific gut-wall efflux or intestinal metabolism evidence.",
      "card_ids": ["C68","C72"]
    },
    {
      "claim": "L4 human absorption records for close morphinan analogs show complete or near-complete intestinal absorption (dextromethorphan complete; codeine Fa 95% and >90%), and rat fraction-absorbed values of 0.92-0.99 for a polar morphine glucuronide support the absorption component of the high prediction.",
      "card_ids": ["C53","C54","C55","C56","C57","C58","C62","C64"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C65","C66","C69","C71"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability or matched oral/IV exposure measurement for hydromorphone under rifampin co-treatment.",
    "No hydromorphone-specific fraction-absorbed, permeability, gut-wall efflux, or intestinal metabolism measurement; L4/L5 records are for close analogs or unrelated compounds.",
    "No quantification of rifampin's induction of first-pass glucuronidation or efflux transporters on hydromorphone exposure.",
    "Rifampin co-treatment could lower F, but no affirmative evidence indicates it drops below 20%."
  ],
  "decision_summary": "Retained and strengthened high (F >= 20%) because L5 gut-wall/intestinal records for close morphinan and rigid phenolic alkaloid analogs show good passive absorption and no efflux limitation, while no record provides affirmative evidence that hydromorphone under rifampin has F < 20%; confidence remains moderate due to absence of direct hydromorphone/rifampin F data."
}

